// Package validation holds the results of NetLogo reference runs and helpers to compare gobees with them.
//
// The reference data (netlogo_<name>.go) are generated by trans/validation/aggregate_netlogo.py from the
// BehaviorSpace output of trans/validation/run_netlogo_experiment.ps1. See trans/validation/README.md.
package validation

import (
	"encoding/csv"
	"fmt"
	"slices"
	"strconv"
	"strings"
)

// Quantiles of a metric at one step over all NetLogo runs.
type Quantiles struct {
	N                       int
	Q05, Q25, Q50, Q75, Q95 float64
}

// Key identifies a metric at a step.
type Key struct {
	Step   int
	Metric string
}

// Parse reads the quantile table of a generated reference file.
func Parse(table string) (map[Key]Quantiles, error) {
	rows, err := csv.NewReader(strings.NewReader(table)).ReadAll()
	if err != nil {
		return nil, err
	}
	result := map[Key]Quantiles{}
	for _, r := range rows[1:] {
		step, err := strconv.Atoi(r[0])
		if err != nil {
			return nil, err
		}
		n, err := strconv.Atoi(r[2])
		if err != nil {
			return nil, err
		}
		q := make([]float64, 5)
		for i := range q {
			if q[i], err = strconv.ParseFloat(r[3+i], 64); err != nil {
				return nil, fmt.Errorf("step %d, %s: %w", step, r[1], err)
			}
		}
		result[Key{step, r[1]}] = Quantiles{n, q[0], q[1], q[2], q[3], q[4]}
	}
	return result, nil
}

// Median returns the median of the values.
func Median(values []float64) float64 {
	v := slices.Clone(values)
	slices.Sort(v)
	n := len(v)
	if n%2 == 1 {
		return v[n/2]
	}
	return (v[n/2-1] + v[n/2]) / 2
}
